/**
 * Disclosure list (`design/components/accordion.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/accordion.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import * as zag from '@zag-js/accordion'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementList,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { useKeyedPresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/structure/accordion.module.css'

export type AccordionHeadingLevel = NonNullable<AccordionProps['headingLevel']>

export interface AccordionItem {
  value: string
  label: string
  content: JSX.Element | string
  disabled?: boolean
}

export interface AccordionProps {
  /**
   * The open item may be closed again, leaving the list shut.
   */
  collapsible?: boolean
  defaultValue?: string | string[]
  headingLevel?: 3 | 4
  items: AccordionItem[]
  onValueChange?: ((value: string) => void) | ((value: string[]) => void)
  type?: 'single' | 'multiple'
  value?: string | string[]
}

/** Disclosure list. */
export default function Accordion(given: AccordionProps): JSX.Element {
  const props = mergeProps(
    { headingLevel: 3, type: 'single' } as Defaults<AccordionProps, 'headingLevel' | 'type'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const heights = createCell(new Map())
    const regions = elementList<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          multiple: props.type === 'multiple',
          collapsible: props.type === 'multiple' || (props.collapsible ?? true),
          value:
            props.value === undefined
              ? undefined
              : Array.isArray(props.value)
                ? props.value
                : props.value === ''
                  ? []
                  : [props.value],
          defaultValue:
            props.defaultValue === undefined
              ? undefined
              : Array.isArray(props.defaultValue)
                ? props.defaultValue
                : [props.defaultValue],
          onValueChange: (details) => {
            ;(props.onValueChange as unknown as ((...args: unknown[]) => unknown) | undefined)?.(
              props.type === 'multiple' ? details.value : (details.value[0] ?? ''),
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const regionPresent = useKeyedPresence(
      () => api.value.value,
      () => regions.value,
      (element) =>
        props.items.find(
          (item) => api.value.getItemContentProps({ value: item.value }).id === element.id,
        )?.value,
    )
    const effect1 = () => {
      heights.value = new Map(
        (regions.value ?? []).map((region) => [region.id, region.scrollHeight + 'px']),
      )
    }
    watchEffect(
      createMemo(() => api.value.value),
      effect1,
      true,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'Accordion',
        element: () => root.value,
        state: () => ({
          value: api.value.value,
          items: props.items.map((item) => ({
            id: item.value,
            label: item.label,
            ...(item.disabled === true ? { disabled: true } : {}),
          })),
        }),
        actions: {
          expand: {
            argument: 'id',
            run: (value) =>
              api.value.value.includes(value) ||
              api.value.setValue(props.type === 'multiple' ? [...api.value.value, value] : [value]),
          },
          collapse: {
            argument: 'id',
            run: (value) =>
              (() => {
                if (!api.value.value.includes(value)) return
                if (props.type !== 'multiple' && !(props.collapsible ?? true)) {
                  throw new Error(
                    'This accordion keeps one item open; expand another item instead.',
                  )
                }
                api.value.setValue(api.value.value.filter((shown) => shown !== value))
              })(),
          },
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        {...mergeParts(api.value.getRootProps(), {
          class: styles.root,
          'data-member': 'accordion',
        })}
        ref={root.attach}
      >
        <Each of={props.items} by={(item) => item.value} renew>
          {(item) => (
            <div
              {...mergeParts(
                api.value.getItemProps({ value: item.value, disabled: item.disabled }),
                { class: styles.item },
              )}
            >
              <Dynamic component={props.headingLevel === 4 ? 'h4' : 'h3'} class={styles.header}>
                {/* trigger */}
                <button
                  {...mergeParts(
                    api.value.getItemTriggerProps({ value: item.value, disabled: item.disabled }),
                    { class: styles.trigger, 'data-accordion-part': 'trigger' },
                  )}
                >
                  <span class={styles.label}>{item.label}</span>
                  <span class={styles.chevron}>
                    <Icon name="down" />
                  </span>
                </button>
              </Dynamic>
              {/* region */}
              <div
                {...mergeParts(
                  api.value.getItemContentProps({ value: item.value, disabled: item.disabled }),
                  {
                    class: styles.content,
                    style: {
                      '--radix-accordion-content-height': heights.value.get(
                        api.value.getItemContentProps({
                          value: item.value,
                          disabled: item.disabled,
                        }).id,
                      ),
                    },
                    hidden: !regionPresent().has(item.value),
                    'data-accordion-part': 'region',
                  },
                )}
                ref={regions.attach}
              >
                <div class={styles.inner}>
                  {typeof item.content === 'string' ? item.content : item.content}
                </div>
              </div>
            </div>
          )}
        </Each>
      </div>
    )
  })
}
